(function(){
  const style=document.createElement("style");
  style.textContent=".img-lightbox-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;z-index:9999;opacity:0;transition:opacity .15s ease;padding:24px;box-sizing:border-box;}.img-lightbox-overlay.visible{opacity:1;}.img-lightbox-overlay img{max-width:90vw;max-height:90vh;border-radius:6px;box-shadow:0 8px 40px rgba(0,0,0,0.5);cursor:zoom-out;}.img-lightbox-close{position:absolute;top:16px;right:20px;background:none;border:none;color:#fff;font-size:32px;line-height:1;cursor:pointer;opacity:0.85;padding:4px 10px;}.img-lightbox-close:hover{opacity:1;}";
  document.head.appendChild(style);
  let overlay=null;
  function close(){
    if(!overlay)return;
    overlay.classList.remove("visible");
    const el=overlay;
    setTimeout(()=>{el.remove();},150);
    overlay=null;
    document.removeEventListener("keydown",onKey);
  }
  function onKey(e){"Escape"===e.key&&close();}
  window.openImageLightbox=function(src){
    close();
    overlay=document.createElement("div");
    overlay.className="img-lightbox-overlay";
    const img=document.createElement("img");
    img.src=src;
    img.alt="";
    const closeBtn=document.createElement("button");
    closeBtn.type="button";
    closeBtn.className="img-lightbox-close";
    closeBtn.setAttribute("aria-label","Fermer");
    closeBtn.textContent="\u00d7";
    overlay.append(closeBtn,img);
    overlay.addEventListener("click",e=>{
      if(e.target===overlay)close();
    });
    closeBtn.addEventListener("click",close);
    img.addEventListener("click",close);
    document.body.appendChild(overlay);
    requestAnimationFrame(()=>overlay.classList.add("visible"));
    document.addEventListener("keydown",onKey);
  };
})();
